a.plan_id,
a.device_id,
a.device_name,
a.instance_id,
a.instance_name,
a.position_id,
a.position_name,
a.robot_id,
a.area_id,
a.point_type,
a.cruise_region_ids,
a.create_time,
a.update_time
from u_patrol_plan_attr a
where 1 = 1
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
